style.css:
@-moz-document domain("youtube.com") {
:root {
    --sgg-bg: #f8edf3; /* Main BG: Soft pink */
    --sgg-panel: #f0d9eb; /* Panels: Lilac pink */
    --sgg-text: #5e3259; /* Dark plum text */
    --sgg-muted: #8a567c;
    --sgg-accent: #ffb0d6; /* Candy pink */
    --sgg-hover: #ffe4f2; /* Light highlight pink */
    --sgg-icon: #c05786; /* Darker pink for icons */
    --sgg-border: rgba(255, 192, 225, 0.2);
  }

  html, body, ytd-app {
    background-color: var(--sgg-bg) !important;
    color: var(--sgg-text) !important;
    font-family: 'Caveat', cursive !important;
  }

  * {
    font-family: 'Caveat', cursive !important;
  }

  /* Video Cards */
  ytd-rich-item-renderer,
  ytd-video-renderer,
  ytd-compact-video-renderer {
    background-color: var(--sgg-panel) !important;
    border-radius: 16px !important;
    border: 1px solid var(--sgg-border);
    box-shadow: 0 0 10px rgba(255, 192, 225, 0.2);
    transition: all 0.2s ease;
  }

  ytd-rich-item-renderer:hover {
    background-color: var(--sgg-hover) !important;
    transform: scale(1.01);
    box-shadow: 0 0 15px rgba(255, 176, 214, 0.4);
  }

  /* Tabs bar (All, Music, Mixes) */
  #chips-wrapper,
  ytd-feed-filter-chip-bar-renderer {
    background-color: var(--sgg-panel) !important;
    border: none !important;
  }

  tp-yt-paper-chip {
    background-color: var(--sgg-panel) !important;
    color: var(--sgg-text) !important;
    border-radius: 9999px !important;
    box-shadow: 0 0 4px rgba(255, 176, 214, 0.2);
  }

  tp-yt-paper-chip[is-selected] {
    background-color: var(--sgg-accent) !important;
    color: #3a2a37 !important;
  }

  /* Comments & Text */
  yt-formatted-string,
  ytd-comment-renderer,
  #content-text {
    color: var(--sgg-text) !important;
  }

  /* Sidebar */
  ytd-guide-section-renderer,
  ytd-guide-entry-renderer,
  #guide {
    background-color: var(--sgg-bg) !important;
    color: var(--sgg-text) !important;
  }

  ytd-guide-entry-renderer:hover {
    background-color: #f3d2e4 !important;
  }

  /* Icons (thumbs up, home, etc.) */
  yt-icon,
  yt-icon-shape,
  path {
    fill: var(--sgg-icon) !important;
    color: var(--sgg-icon) !important;
  }

  /* Search */
  input#search,
  ytd-searchbox input {
    background-color: #f3d8e9 !important;
    color: var(--sgg-text) !important;
    border: 1px solid var(--sgg-border) !important;
  }

  /* Player */
  .ytp-chrome-bottom,
  .ytp-chrome-top {
    background: linear-gradient(to top, #ffdef2dd, transparent) !important;
  }

  .ytp-play-progress {
    background-color: var(--sgg-accent) !important;
  }

  /* Scrollbar */
  ::-webkit-scrollbar {
    width: 10px;
  }

  ::-webkit-scrollbar-thumb {
    background: var(--sgg-accent);
    border-radius: 6px;
  }

  ::-webkit-scrollbar-track {
    background: #f5e4f0;
  }

  ::selection {
    background: var(--sgg-accent);
    color: #3a2a37;
  }
}
